∀ {m : ℕ} {v : Breakdown.Space → Breakdown.Space} {G : Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space},
  Breakdown.SteadyCert.IsSecondOrderField m v G H → MeasureTheory.MemLp (fun y => ‖y‖⁻¹ • v y) 2 MeasureTheory.volume

∀ {α : ℝ} {k N : ℕ} {d : Breakdown.SteadyCert.FracCertData k N} {j : Fin k} {p : Fin k → ℝ}
  {D : Breakdown.CellCert.Reduction.AdjointDual k},
  Breakdown.CellCert.Reduction.IsAdjointDual α d j p D → ∀ (l : Fin k), 0 < D.pinScale l

∀ {α : ℝ} {k N : ℕ} {d : Breakdown.SteadyCert.FracCertData k N} {j : Fin k} {p : Fin k → ℝ}
  {D : Breakdown.CellCert.Reduction.AdjointDual k},
  Breakdown.CellCert.Reduction.IsAdjointDual α d j p D → Breakdown.SteadyCert.l2Norm D.dualField ≤ D.dualBound

∀ {α : ℝ} {k N : ℕ} {d : Breakdown.SteadyCert.FracCertData k N} {j : Fin k} {p : Fin k → ℝ}
  {D : Breakdown.CellCert.Reduction.AdjointDual k},
  Breakdown.CellCert.Reduction.IsAdjointDual α d j p D → 0 ≤ D.potentialScale

∀ {m : ℕ} {v : Breakdown.Space → Breakdown.Space} {G : Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space},
  Breakdown.SteadyCert.IsSecondOrderField m v G H → MeasureTheory.LocallyIntegrable H MeasureTheory.volume

∀ {α : ℝ} {k N : ℕ} {d : Breakdown.SteadyCert.FracCertData k N} {j : Fin k} {p : Fin k → ℝ}
  {D : Breakdown.CellCert.Reduction.AdjointDual k},
  Breakdown.CellCert.Reduction.IsAdjointDual α d j p D → 0 ≤ D.inverseSquareBound

∀ {α : ℝ} {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {K : Breakdown.CellCert.CellAnalysis.CellBox}
  {S : Breakdown.CellCert.CellAnalysis.CellScalars} {W : Breakdown.CellCert.Reduction.WeightData},
  Breakdown.CellCert.CellAnalysis.IsCellBox K → Breakdown.CellCert.Reduction.IsWeightTests α c K S W → 0 ≤ W.rHi

∀ (φ : ℝ) (y : Breakdown.Space),
  { re := (Breakdown.CellCert.Reduction.turnBy φ y).ofLp 0, im := (Breakdown.CellCert.Reduction.turnBy φ y).ofLp 1 } =
    Complex.exp (↑φ * Complex.I) * { re := y.ofLp 0, im := y.ofLp 1 }
